style.css:
header svg {
    display: none !important;
}


header {
    position: relative !important;
}


header::before {
    content: "☕ Coffee Songs"; /* your replacement text here */
    font-size: 22px;            /* adjust text size */
    font-weight: bold;
    color: #1DB954 !important;   /* change this color to whatever you want */
    position: absolute;
    left: 200px;                  /* shift from left edge */
    top: 50%;
    transform: translateY(-50%);
    pointer-events: none;        /* doesn’t block clicks */
    z-index: 10;                 /* above other elements */
}
